import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const r = new Readable({ read() {} });
  const p: any = r.toArray();
  console.log(typeof p, p instanceof Promise);
  const r2 = new Readable({ read() {} });
  const q: any = r2.toArray();
  setTimeout(() => r2.destroy(new Error('boom')), 5);
  try { await q; } catch (e: any) { console.log('rejected', e.message); }
  const r3 = new Readable({ read() {} });
  const r4 = new Readable({ read() {} });
  const p3: any = r3.toArray();
  const p4: any = r4.toArray();
  setTimeout(() => { r3.push('x'); r3.push(null); r4.push('y'); r4.push(null); }, 5);
  console.log(String((await p4)[0]), String((await p3)[0]));
}
